struct nglQuad { char data[200]; };

class PanelQuad
{
public:
    virtual ~PanelQuad();
    virtual void Init(float, float, float, float, float, float, float, float, float, float, float, float, float, void *);
    virtual void TurnOn(bool);
    virtual void SetLayer(int);
    virtual void Rotate(float);
    virtual void Rotate(float, float, float);
    virtual void Update(float);
    virtual void Draw(int, float);
    virtual void SetColor(float, float, float, float);
    virtual void SetColor(unsigned int);
    virtual void SetZ(float);
    virtual void SetUV(float, float, float, float);
    virtual bool IsOn() const;
    virtual void SetPos(float, float, float, float);
    virtual void SetPos(float, float);
    virtual void SetPos(float, float, float, float, float, float, float, float);
    virtual void GetPos(float &, float &, float &, float &);
    virtual void SetCenterX(float);
    virtual void SetCenterY(float);
    virtual void SetCenterPos(float, float);
    virtual void GetCenterPos(float &, float &);
};

class TextString
{
public:
    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();
    virtual void setHJustify(int);
    virtual void setVJustify(int);
    virtual void setFont(void *);
    virtual void setButtonScale(float);
    virtual void numberSpacing(bool);
    virtual void changeText(void *);
    virtual void changeScale(float);
    virtual void changePos(float, float);
    virtual void changeX(float);
    virtual void changeY(float);
    virtual void changeZ(int);
};

void adjustCoords(float &, float &);
void nglSetQuadRect(nglQuad *, float, float, float, float);
void nglSetQuadZ(nglQuad *, float);

class PhotoWidget
{
    int display;
    void *vtable;
    PanelQuad *borderPQ;
    int borderCenterX;
    int borderCenterY;
    int borderZ;
    void *photoTexture;
    nglQuad photoQuad;
    nglQuad darkQuad;
    float darkFade;
    float fadeOutAlpha;
    float shownTimer;
    bool timed;
    int photoNum;
    TextString *pointText;
    int score;
    int *scorePtr;

public:
    void SetPosition(const int x, const int y, const int z);
};

void PhotoWidget::SetPosition(const int x, const int y, const int z)
{
	float x1, y1, x2, y2;

	// Move panel quad.
	borderPQ->SetPos(x, y);
	borderZ = z;
	borderPQ->SetZ(borderZ);

	// Get new position.
	borderPQ->GetCenterPos(x1, y1);
	borderCenterX = int(x1);
	borderCenterY = int(y1);
	borderPQ->GetPos(x1, y1, x2, y2);

	// Move text.
	pointText->changePos((x2-x1)/2+x1, y2-25);
	pointText->changeZ(z-10);

	// Move picture quads.
	x1 += 27;
	y1 += 23;
	x2 = x1+128;
	y2 = y1+128;
	adjustCoords(x1, y1);
	adjustCoords(x2, y2);
	nglSetQuadRect(&photoQuad, x1, y1, x2, y2);
	nglSetQuadZ(&photoQuad, z-10);
	nglSetQuadRect(&darkQuad, x1, y1, x2, y2);
	nglSetQuadZ(&darkQuad, z-20);
}
